{
    if (! $this->exists) {
        return $this;
    }

    $this->setRawAttributes(
        $this->setKeysForSelectQuery($this->newQueryWithoutScopes())
            ->useWritePdo()
            ->firstOrFail()
            ->attributes
    );

    $this->load(collect($this->relations)->reject(function ($relation) {
